import numpy as np                                             # noqa: E402
import torch                                                   # noqa: E402
from scipy.spatial import cKDTree                              # noqa: E402

CODE_ROOTS = [
    "/kaggle/input/datasets/faustine649/cell-tracking/cell tracking",
    "/kaggle/input/datasets/faustine649/cell-tracking",
    "/kaggle/input/cell-tracking/cell tracking",
    "/kaggle/input/cell-tracking",
]
code = next((c for c in CODE_ROOTS if pathlib.Path(c, "division_recovery.py").exists()), None)
assert code is not None, "attach faustine649/cell-tracking"
sys.path.insert(0, code)
import division_recovery as dr                                 # noqa: E402
from viz_cells import find_root, geff_path, read_geff, open_image  # noqa: E402

root = find_root(None)
TRAIN_DIR = pathlib.Path(root) / "train"
OUT = pathlib.Path("/kaggle/working")
SCALE = np.array([1.625, 0.40625, 0.40625])
DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
print("device:", DEVICE, torch.__version__, flush=True)

try:
    import ultrack                                             # noqa: E402
    import skimage                                             # noqa: E402
    print("scikit-image", skimage.__version__, flush=True)
    from ultrack import MainConfig, Tracker                    # noqa: E402
    print("ultrack", getattr(ultrack, "__version__", "?"), flush=True)
except Exception as e:  # noqa: BLE001
    print("ULTRACK IMPORT FAILED:", str(e)[:800], flush=True)
    raise

_SCORER_OK = True
try:
    import tracksdata as td                                    # noqa: E402
    from tracking_cellmot.io import open_dataset               # noqa: E402
    from tracking_cellmot.metrics import evaluate as compute_metric, node_recall, per_sample_metrics  # noqa: E402
except Exception as e:  # noqa: BLE001
    _SCORER_OK = False
    print("[degraded] official scorer import failed:", str(e)[:400], flush=True)

MOVIES = [m for m in os.environ.get("UB_MOVIES", "6bba_05b6850b,6bba_05db0fb1,6bba_062c8d37").split(",") if m]
REF = {"6bba_05b6850b": (0.9976, 0.9941, 843, 3, 2, 6136),
       "6bba_05db0fb1": (0.8755, 0.8729, 1106, 84, 77, 67745),
       "6bba_062c8d37": (0.9830, 0.9756, 881, 5, 17, 5572)}
WEIGHT_NAME = os.environ.get("UB_WEIGHTS", "unet-daxi")

# ---- the UNet ---------------------------------------------------------------------
wpath = next((p for p in pathlib.Path("/kaggle/input").rglob(f"{WEIGHT_NAME}.pt")), None)
assert wpath is not None, f"{WEIGHT_NAME}.pt not found -- attach faustine649/ultrack-unet-weights"
NET = torch.jit.load(str(wpath), map_location=DEVICE)
NET.eval()
print("weights:", wpath, flush=True)


def norm_pct(v, lo=1.0, hi=99.9):
    a, b = np.percentile(v, [lo, hi])
    return np.clip((v - a) / max(1e-6, b - a), 0, 1).astype(np.float32)


def unet_maps(vol):
    x = torch.from_numpy(np.ascontiguousarray(norm_pct(vol.astype(np.float32))))[None, None].to(DEVICE)
    with torch.no_grad():
        y = NET(x)
    if isinstance(y, (tuple, list)):
        y = torch.cat([t.float() for t in y], dim=1)
    y = y.float()[0].cpu().numpy()
    if y.min() < -0.01 or y.max() > 1.01:
        y = 1.0 / (1.0 + np.exp(-np.clip(y, -60, 60)))
    return y[0], y[1]          # foreground, contours (probe: c0 blob-like, c1 thin)


# ---- sites (hplace's table: swap = GT child A of a swap pair, ctrl = ordinary cell) ----
SITES_B64 = ""


def load_sites():
    raw = gzip.decompress(base64.b64decode(SITES_B64)).decode()
    lines = [ln.strip() for ln in raw.strip().splitlines() if ln.strip()]
    hdr = lines[0].split(",")
    rows = []
    for ln in lines[1:]:
        v = ln.split(",")
        r = dict(zip(hdr, v))
        for k in hdr[3:]:
            r[k] = float(r[k]) if r[k] not in ("", "nan") else float("nan")
        r["t"] = int(r["t"])
        rows.append(r)
    return rows


SITES = defaultdict(list)
for r_ in load_sites():
    SITES[r_["dataset"]].append(r_)


def make_config(workdir):
    cfg = MainConfig()
    cfg.data_config.working_dir = pathlib.Path(workdir)
    cfg.data_config.n_workers = 1          # v2: ultrack spawns workers with the 'spawn' context, which re-imports this script; single process
    s = cfg.segmentation_config
    s.threshold = 0.4
    s.min_area = 300
    s.max_area = 25000
    s.min_frontier = 0.0
    s.n_workers = 1          # v2: ultrack spawns workers with the 'spawn' context, which re-imports this script; single process
    lk = cfg.linking_config
    lk.max_distance = 10.0
    lk.max_neighbors = 5
    lk.distance_weight = 0.0
    lk.z_score_threshold = 5.0
    lk.n_workers = 1          # v2: ultrack spawns workers with the 'spawn' context, which re-imports this script; single process
    tr = cfg.tracking_config
    tr.appear_weight = -0.1
    tr.disappear_weight = -0.1
    tr.division_weight = -0.1
    tr.power = 4
    tr.bias = 0.0
    tr.link_function = "power"
    tr.window_size = 25
    tr.overlap_size = 5
    tr.solution_gap = 0.001
    tr.time_limit = 3600
    tr.n_threads = 4
    tr.solver_name = "CBC"
    return cfg


def score_one(gp, name):
    dset = open_dataset(root / "train" / name, require_tracks=True, load_image=False)
    res_ = td.graph.IndexedRXGraph.from_geff(str(gp))
    g = res_[0] if isinstance(res_, tuple) else res_
    er = compute_metric(g, dset.tracks, scale=dset.scale)
    rec = (node_recall(g, dset.tracks) if g.num_edges() > 0 and g.num_nodes() > 0 else 0.0)
    gt = read_geff(geff_path(root, "train", name))
    est = gt["extra"].get("estimated_number_of_nodes")
    return per_sample_metrics(er, float(est) if est else float("nan"), rec)


def q(v, f):
    v = np.array([x for x in v if x == x], float)
    return float(np.quantile(v, f)) if len(v) else float("nan")


SUMMARY = []
for k_, name in enumerate(MOVIES):
    if time.time() - T_ALL > BUDGET_S:
        print(f"BUDGET: stopping before {name}", flush=True)
        break
    tm = time.time()
    img = open_image(TRAIN_DIR / f"{name}.zarr")
    T = img.shape[0]
    Z, Y, X = img.shape[1:]
    fg = np.zeros((T, Z, Y, X), np.float32)
    ct = np.zeros((T, Z, Y, X), np.float32)
    for t in range(T):
        f_, c_ = unet_maps(np.asarray(img[t]))
        fg[t] = f_
        ct[t] = c_
    print(f"\n=== [{k_ + 1}/{len(MOVIES)}] {name}: T={T} {Z}x{Y}x{X}; UNet {time.time() - tm:.0f}s; "
          f"fg>0.4 covers {(fg > 0.4).mean():.3f} ===", flush=True)
    workdir = pathlib.Path(f"/kaggle/working/ut_{name}")
    shutil.rmtree(workdir, ignore_errors=True)
    workdir.mkdir(parents=True)
    cfg = make_config(workdir)
    tracker = Tracker(cfg)
    t1 = time.time()
    try:
        tracker.track(foreground=fg, contours=ct, scale=tuple(float(s) for s in SCALE))
    except TypeError as e:
        if "scale" not in str(e):
            raise
        print("  track(scale=) refused:", str(e)[:200], "-> retrying without scale", flush=True)
        tracker.track(foreground=fg, contours=ct, overwrite="all")
    print(f"  ultrack track() {time.time() - t1:.0f}s", flush=True)
    df = tracker.to_pandas(include_parents=True, include_node_ids=True)
    print(f"  columns {list(df.columns)}; nodes {len(df):,}; tracks {df['track_id'].nunique():,}", flush=True)
    ids = df["id"].to_numpy().astype(np.int64)
    par = df["parent_id"].to_numpy().astype(np.int64) if "parent_id" in df.columns else np.full(len(df), -1)
    tt = df["t"].to_numpy().astype(int)
    zyx = df[["z", "y", "x"]].to_numpy(float)
    np.savez_compressed(OUT / f"ultrack_nodes_{name}.npz", id=ids, parent_id=par, t=tt, zyx=zyx.astype(np.float32),
                        track_id=df["track_id"].to_numpy())
    idset = set(ids.tolist())
    edges = [(int(p), int(i)) for p, i in zip(par, ids) if p >= 0 and p in idset]
    kids = defaultdict(int)
    for p, _c in edges:
        kids[p] += 1
    n_div = sum(1 for v in kids.values() if v >= 2)
    print(f"  edges {len(edges):,} (nodes with >= 2 children: {n_div}); nodes/frame {len(df) / T:.0f}; "
          f"our shipped nodes {REF.get(name, (0,)*6)[5]:,}", flush=True)

    # ---- placement against the annotated GT ---------------------------------------
    gt = read_geff(geff_path(root, "train", name))
    g_t = np.asarray(gt["t"], int)
    g_pos = np.stack([np.asarray(gt[c], float) for c in ("z", "y", "x")], axis=1)
    by_t = defaultdict(list)
    for i, t in enumerate(tt):
        by_t[int(t)].append(i)
    trees = {t: cKDTree(zyx[ix] * SCALE) for t, ix in by_t.items()}
    d_all = []
    for i in range(len(g_t)):
        tr_ = trees.get(int(g_t[i]))
        d_all.append(float(tr_.query(g_pos[i] * SCALE, k=1)[0]) if tr_ is not None else float("inf"))
    d_all = np.array(d_all)
    print(f"  placement, all {len(d_all):,} annotated nodes: nearest Ultrack node median {np.median(d_all):.2f} um, "
          f"p75 {np.percentile(d_all, 75):.2f}, within 5 um {np.mean(d_all <= 5):.3f}, within 7 um {np.mean(d_all <= 7):.3f}, "
          f"> 2.5 um {np.mean(d_all > 2.5):.3f}", flush=True)
    for kind in ("swap", "ctrl"):
        ss = [s for s in SITES.get(name, []) if s["kind"] == kind]
        if not ss:
            continue
        dd = []
        for s in ss:
            tr_ = trees.get(s["t"])
            A = np.array([s["gz"], s["gy"], s["gx"]])
            dd.append(float(tr_.query(A * SCALE, k=1)[0]) if tr_ is not None else float("inf"))
        dd = np.array(dd)
        print(f"  placement, {kind} sites (n {len(dd)}): median {np.median(dd):.2f} um, > 2.5 um {np.mean(dd > 2.5):.2f}, "
              f"<= 1.5 um {np.mean(dd <= 1.5):.2f}", flush=True)

    # ---- the official metric on Ultrack's own tracks ----------------------------------
    row = None
    if _SCORER_OK:
        try:
            gp = OUT / "ut_geff" / f"{name}.geff"
            gp.parent.mkdir(parents=True, exist_ok=True)
            shutil.rmtree(gp, ignore_errors=True)
            nodes_arr = np.column_stack([tt, zyx])
            rm = {int(i): k for k, i in enumerate(ids)}
            e_idx = np.array([[rm[a], rm[b]] for a, b in edges], int) if edges else np.zeros((0, 2), int)
            dr._save(str(gp), nodes_arr, e_idx)
            row = score_one(gp, name)
            ref = REF.get(name)
            print(f"  OFFICIAL: adj_J {row['adj_edge_jaccard']:.4f} edge_J {row['edge_jaccard']:.4f} "
                  f"tp/fp/fn {int(row['edge_tp'])}/{int(row['edge_fp'])}/{int(row['edge_fn'])} "
                  f"div tp/fp/fn {int(row['division_tp'])}/{int(row['division_fp'])}/{int(row['division_fn'])} "
                  f"nodes {int(row['num_pred_nodes']):,} node_ratio {row['total_node_ratio']:+.4f}"
                  + (f"   | ours (REF F4HP): adj_J {ref[0]:.4f} edge_J {ref[1]:.4f} tp/fp/fn {ref[2]}/{ref[3]}/{ref[4]} nodes {ref[5]:,}"
                     if ref else ""), flush=True)
        except Exception as e:  # noqa: BLE001
            print("  official scorer failed:", str(e)[:600], flush=True)
    SUMMARY.append((name, len(df), len(edges), float(np.median(d_all)), float(np.mean(d_all <= 7)), row))
    shutil.rmtree(workdir, ignore_errors=True)
    del fg, ct, df, img
    gc.collect()
    print(f"  movie done in {(time.time() - tm) / 60:.1f} min (total {(time.time() - T_ALL) / 60:.1f} min)", flush=True)

print(f"\n=== ULTRACKBENCH SUMMARY ({WEIGHT_NAME}, pct 1-99.9, sparse_zebrafish config, CBC) ===", flush=True)
for name, nn, ne, dmed, r7, row in SUMMARY:
    ref = REF.get(name)
    line = f"  {name}: nodes {nn:,} edges {ne:,}; annotated-node placement median {dmed:.2f} um, within 7 um {r7:.3f}"
    if row is not None:
        line += f"; official adj_J {row['adj_edge_jaccard']:.4f} edge_J {row['edge_jaccard']:.4f}"
    if ref:
        line += f"  | ours adj_J {ref[0]:.4f} edge_J {ref[1]:.4f}"
    print(line, flush=True)
print(f"\nULTRACKBENCH DONE in {(time.time() - T_ALL) / 60:.1f} min", flush=True)
print("ULTRACKBENCH OK" if len(SUMMARY) == len(MOVIES) else f"ULTRACKBENCH INCOMPLETE ({len(SUMMARY)} of {len(MOVIES)})", flush=True)
